Lemma ram_brk_node_at (pc : Z) :
  (pc = 0x9e8a0 \/ pc = 0x9e8dc) -> forall cur req, req <> 0 ->
  impl rsegs (at_node rsegs) (enode (NBrk req) (dec_brk cur req))
